    lore_title: 'OCCUPY MARS',
    lore_body: '<p>The year is <span class="lore-highlight">2157</span>. Earth is dying. Rising seas have swallowed the great coastal cities. The air itself has become poison. Seven billion souls cling to a world that no longer wants them.</p><p>But humanity refused to go quietly into the dark.</p><p>The <span class="lore-highlight">ARES INITIATIVE</span> — a desperate, last-chance mission — launched a fleet of colony ships toward the Red Planet. After three brutal years crossing the void of space, the survivors made landfall on <span class="lore-red">Mars</span>.</p><p>They found no paradise. Only red dust, freezing winds, and endless silence. But they also found something unexpected: <span class="lore-cyan">Rare mineral deposits</span> buried deep beneath the Martian surface — resources powerful enough to build a new civilization... or tear one apart.</p><p>Now, factions wage war across the crimson wastes. <span class="lore-highlight">Sector Governors</span> rule their domains with iron fists. Raiders <span class="lore-red">hijack</span> territory under cover of sandstorms. Supply rockets crash-land with precious cargo, and only the fastest survive to claim the spoils.</p><p>There is no law here. No government. No rescue coming.<br>There is only <span class="lore-red">Mars</span>. And those bold enough to <span class="lore-highlight">occupy</span> it.</p>',
