    help_currency_body: 'USDT: 영토 구매/하이잭에 사용하는 스테이블코인. 지갑에서 입금하세요.\nPP (Potato Points): 영토 수확으로 얻는 게임 내 화폐. PP를 USDT로 교환하거나 아이템/코스메틱 구매에 사용하세요.',
    help_weather: '날씨 이벤트',
    help_weather_body: '화성 날씨가 게임에 영향을 줍니다! 모래폭풍: 방어↓ 채굴↑. 태양 플레어: 채굴 2배, 쉴드↓. 유성우: 보너스 PP 드랍. 먼지 소용돌이: 클레임 비용↓ 공격↑.',
    help_about: 'OCCUPY MARS 소개',
    help_about_body: 'Occupy Mars는 화성 위 블록체인 영토 게임입니다!',
    help_game_crash: 'CRASH',
    help_game_crash_body: '로켓이 발사되고 배율이 올라갑니다! 베팅 후 폭발 전에 캐시아웃하세요. 오래 기다릴수록 보상이 커지지만, 캐시아웃 전에 폭발하면 전부 잃습니다. PP로 베팅.',
    help_game_mines: 'MINES',
    help_game_mines_body: '5x5 그리드에 보석과 지뢰가 숨겨져 있습니다. 지뢰 수를 선택하세요(많을수록 배율↑). 타일을 하나씩 열어보세요 — 보석마다 당첨금 증가. 지뢰를 밟으면 끝! 언제든 캐시아웃 가능.',
    help_game_sandstorm: 'COINFLIP',
    help_game_sandstorm_body: '클래식 동전 던지기. HEADS 또는 TAILS 선택하고 베팅, 뒤집기. 맞추면 1.96배. 간단하고 빠른 50/50 게임.',
    help_game_meteorite: 'DICE',
    help_game_meteorite_body: '주사위 굴리기! 목표 범위를 설정하세요(좁을수록 배율↑). 결과가 범위 안에 들면 승리. 위험 대 보상을 취향에 맞게 조절.',
    help_game_hilo: 'HI-LO',
    help_game_hilo_body: '카드가 한 장 공개됩니다. 다음 카드가 더 높을지 낮을지 맞추세요. 맞출 때마다 배율 증가. 맞춘 후 언제든 캐시아웃 가능, 또는 더 큰 보상을 위해 계속! 틀리면 전부 잃습니다.',
    lore_era: '머지않은 미래, 그리 멀지 않은 행성에서...',
    lore_title: 'OCCUPY MARS',
    lore_body: '<p><span class="lore-highlight">2157년</span>. 지구는 죽어가고 있다. 해수면 상승이 거대한 해안 도시들을 삼켰다. 공기 자체가 독이 되었다. 70억 영혼이 더 이상 그들을 원하지 않는 세계에 매달려 있다.</p><p>하지만 인류는 조용히 사라지길 거부했다.</p><p><span class="lore-highlight">아레스 이니셔티브</span> — 절박한 최후의 미션 — 이 붉은 행성을 향해 식민 함대를 발사했다. 우주의 공허를 가로지르는 3년간의 잔혹한 여정 끝에, 생존자들은 <span class="lore-red">화성</span>에 착륙했다.</p><p>낙원은 없었다. 붉은 먼지, 얼어붙는 바람, 끝없는 정적뿐. 하지만 예상치 못한 것을 발견했다: 화성 지표면 깊숙이 묻힌 <span class="lore-cyan">희귀 광물 매장지</span> — 새로운 문명을 건설하거나... 산산조각 낼 수 있는 자원.</p><p>이제 세력들이 진홍빛 황무지에서 전쟁을 벌인다. <span class="lore-highlight">섹터 총독</span>들이 철권으로 영토를 지배한다. 약탈자들이 모래폭풍을 틈타 영토를 <span class="lore-red">하이잭</span>한다. 보급 로켓이 귀중한 화물과 함께 추락하고, 가장 빠른 자만이 전리품을 차지한다.</p><p>여기에 법은 없다. 정부도 없다. 구조대도 오지 않는다.<br>오직 <span class="lore-red">화성</span>만이 있을 뿐. 그리고 그것을 <span class="lore-highlight">점령</span>할 만큼 대담한 자들.</p>',
    lore_tagline: '너의 영토. 너의 규칙. 너의 행성.',
