    lore_era: '遠くない未来、そう遠くない惑星で...',
    lore_title: 'OCCUPY MARS',
    lore_body: '<p><span class="lore-highlight">2157年</span>。地球は死にかけている。海面上昇が偉大な沿岸都市を飲み込んだ。大気そのものが毒と化した。70億の魂が、もはや彼らを望まない世界にしがみついている。</p><p>しかし人類は静かに闇に消えることを拒んだ。</p><p><span class="lore-highlight">アレス・イニシアチブ</span> — 絶望的な最後のミッション — が赤い惑星へ植民船団を発進させた。宇宙の虚空を渡る過酷な3年間の後、生存者たちは<span class="lore-red">火星</span>に着陸した。</p><p>楽園はなかった。赤い砂塵、凍てつく風、果てしない静寂だけ。だが予想外のものを発見した：火星の地表深くに埋まる<span class="lore-cyan">希少鉱物の鉱脈</span> — 新文明を築くか...破壊するかの力を持つ資源。</p><p>今、勢力が真紅の荒野で戦争を繰り広げる。<span class="lore-highlight">セクター総督</span>が鉄拳で領土を支配する。略奪者が砂嵐に紛れて領土を<span class="lore-red">ハイジャック</span>する。補給ロケットが貴重な積荷と共に墜落し、最も速い者だけが戦利品を手にする。</p><p>ここに法はない。政府もない。救助も来ない。<br>あるのは<span class="lore-red">火星</span>だけ。そしてそれを<span class="lore-highlight">占領</span>する勇気を持つ者たち。</p>',
    lore_tagline: 'お前の領土。お前のルール。お前の惑星。',
    lore_close: '火星へ突入',
