    help_about: '关于OCCUPY MARS',
    help_about_body: 'Occupy Mars是火星上的区块链领土游戏！',
    help_game_crash: 'CRASH',
    help_game_crash_body: '火箭发射，倍率上升！在爆炸前提现。等待越久奖励越高，但如果在提现前爆炸则全部损失。用PP下注。',
    help_game_mines: 'MINES',
    help_game_mines_body: '5x5网格中隐藏着宝石和地雷。选择地雷数量（越多倍率越高）。逐个翻开方块——每颗宝石增加奖金。踩到地雷就结束！随时可以提现。',
    help_game_sandstorm: 'COINFLIP',
    help_game_sandstorm_body: '火星风格抛硬币！选择DUST或STORM，下注，翻转。赢了=1.96倍。简单快速的50/50概率游戏。',
    help_game_meteorite: 'DICE',
    help_game_meteorite_body: '掷骰子！设置目标范围（范围越窄倍率越高）。结果在范围内则获胜。根据偏好调整风险与回报。',
    help_game_hilo: 'HI-LO',
    help_game_hilo_body: '翻开一张牌。猜下一张牌是更高还是更低。每次猜对倍率增加。猜对后随时可以提现，或继续追求更大奖励！猜错则全部损失。',
    lore_era: '不远的未来，在一颗不太遥远的星球上...',
    lore_title: 'OCCUPY MARS',
    lore_body: '<p><span class="lore-highlight">2157年</span>。地球正在死去。海平面上升吞没了伟大的沿海城市。空气本身变成了毒药。70亿灵魂紧紧抓住一个不再需要他们的世界。</p><p>但人类拒绝悄然消逝于黑暗之中。</p><p><span class="lore-highlight">战神计划</span> — 一次孤注一掷的最后任务 — 向红色星球发射了殖民舰队。经过穿越太空虚空的三年残酷旅程，幸存者们降落在了<span class="lore-red">火星</span>上。</p><p>这里没有天堂。只有红色尘土、刺骨寒风和无尽的沉寂。但他们发现了意想不到的东西：深埋在火星地表之下的<span class="lore-cyan">稀有矿藏</span> — 足以建造新文明……或将其撕裂的资源。</p><p>如今，各势力在猩红荒原上征战。<span class="lore-highlight">区域总督</span>以铁腕统治自己的领地。掠夺者趁沙暴<span class="lore-red">劫持</span>领土。补给火箭携带珍贵货物坠落，只有最快的人才能夺取战利品。</p><p>这里没有法律。没有政府。没有救援会来。<br>只有<span class="lore-red">火星</span>。以及那些敢于<span class="lore-highlight">占领</span>它的人。</p>',
    lore_tagline: '你的领土。你的规则。你的星球。',
