function t(key){
  var lang = normalizeLang(LANG);
  return (I18N[lang]&&I18N[lang][key]) || I18N.en[key] || key;
}
function tl(en,ko,ja,zh,id,vi,th){
  var map = { en:en, ko:ko, ja:ja, zh:zh, id:id, vi:vi, th:th };
  return map[normalizeLang(LANG)] || en;
}
